@namespace xul "http://www.mozilla.org/keymaster/gatekeeper/there.is.only.xul";

form {
  --hub-input-bg-color: light-dark(var(--color-surface-base), #18181b);
  --hub-select-color: light-dark(var(--color-text-base), currentColor);
  --hub-floating-button-inset-block-end: 168px;
  --hub-menulist-color: var(--color-text-base);
  --hub-menulist-background-color: var(--color-surface-subtle);
  --hub-menulist-background-color-hover-focus-open: var(--color-surface-base);
  --hub-menulist-border-color: var(--color-surface-border);
  --hub-menulist-border-color-hover-focus-open: var(--color-surface-border-intense);
  --hub-menulist-outline-offset-color: var(--color-primary-default);
  --hub-menulist-label-color: var(--color-text-base);
  --hub-menupopup-border-color: var(--color-surface-border);
  --hub-menuitem-color-selected: var(--color-surface-base);
  --hub-menuitem-background-color-selected: var(--color-primary-default);
  --hub-form-input-line-height: 1em;
  --hub-form-label-font-size: 1rem;
  --hub-form-label-line-height: 1.5rem;
  --hub-form-label-padding: var(--space-step);
  --hub-form-label-height: calc(var(--hub-form-label-line-height) + 2 * var(--hub-form-label-padding));
  --hub-form-input-block-padding: 12px;

  grid-row: header / footer;

  input[type="checkbox"]:not(.toggle-checkbox) {
    box-sizing: border-box;
    inline-size: 16px;
    block-size: 16px;
    border: 1px solid var(--color-surface-border-intense);
    border-radius: 4px;
    appearance: none;
    background-color: var(--color-surface-lower);

    &:disabled {
      border: 1px solid var(--color-surface-border);
      background-color: var(--color-surface-subtle);

      & + .checkbox-label {
        color: var(--color-text-muted);
      }
    }

    &:checked {
      -moz-context-properties: fill, fill-opacity, stroke, stroke-opacity;
      content: url("chrome://messenger/skin/overrides/check.svg");
      background-color: var(--color-primary-default);
      border-color: var(--color-primary-hover);
      fill: var(--color-surface-base);

      &:disabled {
        background-color: var(--color-surface-border);
        border-color: var(--color-surface-border);
        fill: var(--color-text-muted);
      }
    }
  }

  .checkbox-label {
    color: var(--color-text-base);
    font-weight: 400;
  }

  .toggle-group .toggle-label {
    font-size: 1rem;
    font-weight: 500;
    color: var(--color-primary-hover);
  }

  label {
    font-size: var(--hub-form-label-font-size);
    line-height: var(--hub-form-label-line-height);
    font-weight: 600;
    color: var(--hub-menulist-label-color);

    &.animated {
      position: absolute;
      background-color: var(--hub-input-bg-color);
      border-radius: 3px;
      transform-origin: left center;
      color: var(--color-text-secondary);
      padding: var(--hub-form-label-padding);
      margin-inline-start: 7px;
      font-weight: 400;
      cursor: text;

      @media (prefers-reduced-motion: no-preference) {
        transition:
          transform 200ms,
          color 200ms,
          font-weight 200ms,
          background-color 200ms;
      }
    }
  }

  label:has(+ .input-control input:required)::after,
  input:required + label::after {
    content: "*";
    color: var(--color-text-critical);
  }

  .selected-option {
    padding-block: 13px;
    padding-inline: 10px;
    background: var(--color-surface-subtle);
    border: 1px solid var(--color-surface-border);
    margin-block: 4px;
    border-radius: 2px;
    color: var(--hub-select-color);
    font-weight: 400;
  }

  .input-textarea {
    resize: vertical;
  }

  .input-field,
  .input-textarea {
    flex: 1;
    font-size: 1.2rem;
    line-height: var(--hub-form-input-line-height);
    margin-inline: 0;
    padding-block: var(--hub-form-input-block-padding);
    padding-inline: 9px 30px;
    border: 1px solid var(--color-surface-border);
    border-radius: var(--button-border-radius);
    background-color: var(--hub-input-bg-color);
    font-weight: 300;
    max-inline-size: 100%;

    &[type="password"] {
      padding-inline-end: 9px;
    }

    &[type="url"] {
      margin-block: 4px;
    }

    &::placeholder {
      font-weight: 300;
      color: var(--color-text-muted);
    }

    &.animated {
      &::placeholder {
        color: transparent;
      }
    }

    &:focus {
      border-color: var(--selected-item-color);
    }

    &:focus-visible {
      outline: none;
    }

    &:focus + label.animated,
    &:not(:placeholder-shown) + label.animated {
      transform: translateY(-102%);
      font-weight: 600;
      cursor: default;
      background-color: var(--color-surface-base);
    }

    &.number-input {
      padding-inline-end: 0;

      &::-moz-number-spin-box {
        block-size: 100%;
        padding-block: var(--hub-form-input-block-padding);
        inline-size: 22px;
        border-inline-start: 1px solid var(--color-surface-border);
        border-inline-end: 0;
        border-start-end-radius: var(--hub-input-border-radius);
        border-end-end-radius: var(--hub-input-border-radius);
        background: var(--color-surface-subtle);
        cursor: pointer;
        position: relative;
        z-index: 2;
      }

      &::-moz-number-spin-up,
      &::-moz-number-spin-down {
        appearance: none;
        padding: calc(var(--hub-form-input-block-padding) / 2);
        -moz-context-properties: stroke;
        stroke: currentColor;
        cursor: pointer;
      }

      &::-moz-number-spin-up {
        border-block-end: 1px solid var(--color-surface-border);
        content: var(--icon-nav-up-sm);
      }

      &::-moz-number-spin-down {
        border-block-start: 1px solid var(--color-surface-subtle);
        content: var(--icon-nav-down-sm);
      }
    }
  }

  .menulist {
    margin-inline: 0;
    padding-inline-start: 6px;
    padding-block: 12px;
    line-height: 1.5;
    border: 1px solid var(--hub-menulist-border-color);
    border-radius: var(--hub-input-border-radius);
    background-color: var(--hub-menulist-background-color);

    &:hover,
    &[open="true"]:not([disabled]),
    &:focus-visible {
      border-color: var(--hub-menulist-border-color-hover-focus-open);
      background-color: var(--hub-menulist-background-color-hover-focus-open);
    }

    &:focus-visible {
      outline: 2px solid var(--hub-menulist-outline-offset-color);
      outline-offset: var(--focus-outline-offset);

      /* Needed to override toolkit style */
      &[open="true"] {
        outline: none;
      }
    }
  }

  .menulist,
  .input-field {
    & ~ .input-error-message {
      color: light-dark(var(--color-critical-default), var(--color-critical-pressed));
      display: none;
      position: absolute;
      inset-block-end: calc(-1 * var(--hub-form-input-line-height) - var(--space-step));
